import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Navbar.css';

function Navbar() {
  const [wishlistCount, setWishlistCount] = useState(0);

  useEffect(() => {
    const updateCount = () => {
      const saved = JSON.parse(localStorage.getItem('wishlistItems')) || [];
      setWishlistCount(saved.length);
    };

    updateCount();
    window.addEventListener('wishlistUpdated', updateCount);
    window.addEventListener('storage', updateCount);

    return () => {
      window.removeEventListener('wishlistUpdated', updateCount);
      window.removeEventListener('storage', updateCount);
    };
  }, []);

  return (
    <nav className="navbar">
      <div className="nav-logo">
        <Link to="/">HEXCART</Link>
      </div>

      <div className="nav-search">
        <input type="text" placeholder="Search HEXCART..." />
      </div>

      <div className="nav-right">
        {/* Wishlist positioned to the left of Account & Lists */}
        <Link to="/wishlist" className="nav-item nav-wishlist" style={{ textDecoration: 'none', color: 'inherit', position: 'relative', marginRight: '15px' }}>
          <span>Wishlist</span>
          {wishlistCount > 0 && (
            <span style={{
              position: 'absolute',
              top: '-5px',
              right: '-10px',
              backgroundColor: '#ef4444',
              color: 'white',
              fontSize: '10px',
              fontWeight: 'bold',
              borderRadius: '50%',
              padding: '1px 5px',
            }}>
              {wishlistCount}
            </span>
          )}
        </Link>

        <div className="nav-item">
          <span>Hello, sign in</span>
          <strong>Account & Lists</strong>
        </div>

        <Link to="/cart" className="nav-item nav-cart" style={{ textDecoration: 'none', color: 'inherit' }}>
          <span>Cart</span>
        </Link>
      </div>
    </nav>
  );
}

export default Navbar;
